def normalize_toc_item(md: 'Markdown', token: Dict[str, Any]) -> Tuple[int, str, str]:
    level = token['attrs']['level']
    heading_id = token['attrs']['id']

    # Render children to get HTML, then strip tags to get plain text
    text = ''
    if 'children' in token:
        for child in token['children']:
            text += md.render_token(child, state=None)

    # Strip HTML tags to get plain text
    text = striptags(text)

    return (level, heading_id, text)
